from common import *
import html,copy

NAMES={'control_new':'连续标签 · 同源H20对照','control_old':'连续标签 · 旧标签对照','quantile5':'等样本 · 5档','quantile10':'等样本 · 10档','width5':'等涨幅 · 5档','tails5':'两端少中间多 · 5档'}
KEYS=[('net_ann','扣费净年化'),('net_ann_vol','扣费波动'),('net_sharpe','扣费夏普'),('ann','未扣费年化'),('turnover','日换手')]

def official(doc):return doc['pools']['all']['ensemble']
def cell(doc):return official(doc)['head']['3']['5']
def fmt(value,key):
    if value is None:return '—'
    if key=='rank_ic_mean':return f'{value:.5f}'
    if key=='net_sharpe':return f'{value:.3f}'
    return f'{value*100:.2f}%'
def esc(s):return html.escape(str(s))

def render():
    progress=read(PROGRESS);prepared=read(BASE/'configs/prepared-inputs.json')
    docs={};treatments={}
    if (BASE/'metrics/control-new.json').exists():docs['control_new']=read(BASE/'metrics/control-new.json')
    if (BASE/'metrics/control-old.json').exists():docs['control_old']=read(BASE/'metrics/control-old.json')
    for variant in VARIANTS:
        for treatment in ['new','old']:
            p=BASE/'metrics'/f'{variant}-{treatment}.json'
            if p.exists():treatments[(variant,treatment)]=read(p)
        if (variant,'new') in treatments:docs[variant]=treatments[(variant,'new')]
    complete=all(progress['scientific_candidates'][v]['status'] in ['evaluated_awaiting_registration','completed'] for v in VARIANTS)
    summary={'status':'completed' if complete else 'running','scientific_candidates':4,'completed_candidates':sum(v in docs for v in VARIANTS),'model_fits_started':len(progress['jobs']),'model_fits_succeeded':sum(j['status']=='succeeded' for j in progress['jobs']),'prior_research_fits':111,'cumulative_research_fits':111+len(progress['jobs']),'primary':{},'paired_sensitivity':{},'early_stopping':[]}
    summary['seed_diagnostics']={}
    for name,doc in docs.items():
        summary['primary'][name]={**cell(doc),'rank_ic_mean':official(doc)['h5']['rank_ic_mean']}
        seeds=doc['pools']['all']['seeds'];comp={}
        for key in ['net_ann','net_sharpe']:
            values=[seeds[str(seed)]['head']['3']['5'][key] for seed in SEEDS]
            comp[key]={'seed_min':min(values),'seed_max':max(values),'ensemble':cell(doc)[key],'ensemble_below_all_seeds':cell(doc)[key]<min(values)}
        summary['seed_diagnostics'][name]={'head_agreement':doc.get('diagnostic_seed_head_agreement',{}),'ensemble_vs_components':comp}
    for name in ['control',*VARIANTS]:
        a=docs.get('control_new') if name=='control' else treatments.get((name,'new'))
        b=docs.get('control_old') if name=='control' else treatments.get((name,'old'))
        if a is not None and b is not None:
            summary['paired_sensitivity'][name]={'new':{k:cell(a)[k] for k,_ in KEYS},'old':{k:cell(b)[k] for k,_ in KEYS},'new_minus_old':{k:cell(a)[k]-cell(b)[k] for k,_ in KEYS}}
            hnew=read(BASE/'data'/f'{name}-new-ensemble-heads.json');hold=read(BASE/'data'/f'{name}-old-ensemble-heads.json')
            assert set(hnew['3'])==set(hold['3']) and set(hnew['5'])==set(hold['5'])
            summary['paired_sensitivity'][name]['head_overlap']={str(k):sum(len(set(hnew[str(k)][d])&set(hold[str(k)][d]))/k for d in hnew[str(k)])/len(hnew[str(k)]) for k in [3,5]}
    for j in progress['jobs']:
        if j['status']!='succeeded':continue
        r=read(BASE/'docs'/f'{j["job_id"]}.json');es=r['early_stopping'][0];notes=r['tie_diagnostics']
        reverse=[n['reverse_priority_score'] for n in notes]
        best=float('-inf');best_iter=None;reverse_stop=None
        for i,value in enumerate(reverse,1):
            if value>best:best=value;best_iter=i
            if i-best_iter>=50:reverse_stop=i;break
        row={'variant':j['variant'],'treatment':j['treatment'],'seed':j['seed'],'best_iteration':es['best_iteration'],'observed_rounds':len(r['rounds']),'hit_200_round_cap':len(r['rounds'])==200,'selected_boundary_ties':r['selected_boundary_ties'],'any_top5_boundary_tie_days':max(n['top5_boundary_tie_days'] for n in notes),'reverse_observed_best':best_iter,'reverse_stop_observed':reverse_stop,'reverse_observed_best_differs':best_iter!=es['best_iteration'],'fit_seconds':r['fit_seconds'],'max_rss_GiB':r['max_rss_bytes']/1024**3}
        summary['early_stopping'].append(row)
    write(BASE/'docs/study-summary.json',summary)
    style='body{font-family:-apple-system,"PingFang SC",sans-serif;color:#182635;margin:0;background:#f7f8fa}main{max-width:1240px;margin:auto;padding:30px}h1{font-size:25px}h2{font-size:19px;margin-top:30px}p{line-height:1.65}table{border-collapse:collapse;width:100%;background:white;margin:15px 0;font-size:13px}th,td{padding:9px;border-bottom:1px solid #dfe4e9;text-align:right}th:first-child,td:first-child{text-align:left}th{background:#eef2f5}.note{color:#536273;font-size:13px}.wrap{overflow:auto}a{color:#155faa}img{width:100%;max-width:1100px}.control{background:#edf4fa}'
    page=[f'<!doctype html><html lang="zh"><meta charset="utf-8"><title>标签分级 · H20／patience50</title><style>{style}</style><main>', '<h1>标签分级：去掉细微排名，能否保留预测能力？</h1>',f'<p>状态：{esc(summary["status"])} · {summary["completed_candidates"]}/4 个候选已评估 · 本轮实际启动 {summary["model_fits_started"]} 次拟合（成功 {summary["model_fits_succeeded"]} 次）。前序研究 111 次，本轮另行记账。</p>','<p>用户指定 H20／patience50 配对控制。固定全A、Alpha158+range、M0日期/权重、五种子、200轮上限和Top5×H5早停；只改训练标签。正式全局基线仍为历史v2。2020-08-03～2026-07-31是历史选型窗口，不是独立样本外检验。</p>','<h2>训练前定义与标签检查</h2>','<p>等样本按每日排名分5/10档；两端少中间多按5% / 15% / 60% / 15% / 5%分5档，原始同值不拆散。等涨幅按每日原始H20收益最小值到最大值等距分5档，不做事后缩尾。每档固定序数分数，只在当前训练集确定一次线性缩放以匹配连续目标均值/标准差；同一缩放用于旧标签配对，分档后不再次排名。</p>','<p>5,448,963条训练样本的顺序、特征、缺失掩码及权重固定。旧/新原始规范化标签差106条；三个排名方案均只余1条跨档。若分档后再做每日CSRankNorm，差异会扩散到1129／564／2115条，故未采用该编码。这是输入诊断，不代表模型或收益更稳定。</p>','<div class="wrap"><table><tr><th>候选</th><th>各档样本数（由低到高）</th><th>典型日最大档占比</th><th>极端日最大档占比</th><th>配对标签差异</th></tr>']
    for name in VARIANTS:
        r=prepared['variants'][name];page.append(f'<tr><td>{NAMES[name]}</td><td>{" / ".join(f"{n:,}" for n in r["counts"])}</td><td>{r["daily_max_bin_share"]["median"]:.1%}</td><td>{r["daily_max_bin_share"]["max"]:.1%}</td><td>{r.get("encoded_changes","旧原始收益快照缺失")}</td></tr>')
    page+=['</table></div>']
    boundary=read(BASE/'docs/boundary-jump-audit.json')
    jumps=boundary['graded_float32_target_changes']
    page.append('<p>边界风险：连续标签旧/新最大单条变化约'+f'{boundary["original_float64_max_abs_change"]:.5f}'+ '；保留下来的1条跨档，在等样本5档、等样本10档、两端少5档中分别跳变约'+ ' / '.join(f'{jumps[n]["max_abs_change"]:.3f}' for n in ['quantile5','quantile10','tails5'])+'。减少变化条数并未降低这次扰动的总幅度；分档的边界跳变必须由配对模型结果判断。统一全局方差也不等于保持每日方差或极端样本权重。</p>')
    if docs:
        page+=['<h2>五种子合成信号：Top3×H5正式指标</h2>','<p class="note">净年化采用模型头部收益 ×238/5；波动采用HAC年化标准差，夏普=净年化/波动。这里没有账户CAGR。官方数字来自逐种子日截面z-score后等权合成的一次评估。</p>','<div class="wrap"><table><tr><th>方案</th>'+''.join(f'<th>{label}</th>' for _,label in KEYS)+'<th>全局H5 RankIC</th></tr>']
        for name in ['control_new',*VARIANTS,'control_old']:
            if name not in docs:continue
            doc=docs[name];r=cell(doc)
            page.append(f'<tr class="{"control" if name.startswith("control") else ""}"><td>{NAMES[name]}</td>'+''.join(f'<td>{fmt(r.get(k),k)}</td>' for k,_ in KEYS)+f'<td>{fmt(official(doc)["h5"]["rank_ic_mean"],"rank_ic_mean")}</td></tr>')
        page+=['</table></div>']
        for block,title,columns in [('head_years','分年：主格Top3×H5',[str(y) for y in range(2020,2027)]),('head_regimes','分风格：主格Top3×H5',['D','F','T'])]:
            page.append(f'<h2>{title}</h2>')
            for key,label in KEYS[:3]:
                page.append(f'<h3>{label}</h3><div class="wrap"><table><tr><th>方案</th>'+''.join(f'<th>{c}</th>' for c in columns)+'</tr>')
                for name in ['control_new',*VARIANTS]:
                    if name not in docs:continue
                    page.append(f'<tr><td>{NAMES[name]}</td>'+''.join(f'<td>{fmt(official(docs[name]).get(block,{}).get(c,{}).get("3",{}).get("5",{}).get(key),key)}</td>' for c in columns)+'</tr>')
                page.append('</table></div>')
        page.append('<p class="note">F风格仅覆盖2024年7个月、136个评估日，不能据此推断跨年稳定性。</p>')
    if summary['seed_diagnostics']:
        page+=['<h2>种子间一致性与合成检查</h2>','<p class="note">名单重合取同一交易日两两种子的平均值（10对），在正式推理与正式过滤后计算。种子区间用于诊断，官方数字始终是合成信号的一次评估。</p>','<table><tr><th>方案</th><th>Top3平均重合</th><th>Top5平均重合</th><th>逐种子净年化范围</th><th>合成低于全部种子：净年化/夏普</th></tr>']
        for name,r in summary['seed_diagnostics'].items():
            comp=r['ensemble_vs_components'];a=r['head_agreement'];values=comp['net_ann']
            page.append(f'<tr><td>{NAMES[name]}</td><td>{fmt(a.get("3",{}).get("mean_pairwise_overlap"),"overlap")}</td><td>{fmt(a.get("5",{}).get("mean_pairwise_overlap"),"overlap")}</td><td>{values["seed_min"]:.2%}～{values["seed_max"]:.2%}</td><td>{comp["net_ann"]["ensemble_below_all_seeds"]} / {comp["net_sharpe"]["ensemble_below_all_seeds"]}</td></tr>')
        page.append('</table>')
    if summary['paired_sensitivity']:
        page+=['<h2>配对敏感性：固定其余输入，只替换旧/新标签</h2>','<p>先看两侧绝对表现，再看差距。差距变小也可能来自较好一侧变差。等涨幅缺少对应旧原始收益幅度，本轮不伪造这组106条差异的配对。</p>','<table><tr><th>标签处理</th><th>旧标签净年化</th><th>新标签净年化</th><th>新−旧（百分点）</th><th>Top3名单重合</th><th>Top5名单重合</th></tr>']
        for name,r in summary['paired_sensitivity'].items():page.append(f'<tr><td>{NAMES["control_new"] if name=="control" else NAMES[name]}</td><td>{r["old"]["net_ann"]:.2%}</td><td>{r["new"]["net_ann"]:.2%}</td><td>{r["new_minus_old"]["net_ann"]*100:+.2f}</td><td>{fmt(r.get("head_overlap",{}).get("3"),"overlap")}</td><td>{fmt(r.get("head_overlap",{}).get("5"),"overlap")}</td></tr>')
        page.append('</table>')
    if summary['early_stopping']:
        page+=['<h2>逐种子早停与同分诊断</h2>','<p class="note">反序只改变同分优先顺序，属于同一已观察轨迹的诊断，不参与选轮。未观察到停止时，反序“最佳轮”不能当作新早停规则的最终结果；200轮代表达到上限。</p>','<div class="wrap"><table><tr><th>方案/输入/种子</th><th>选中轮</th><th>实际观察轮</th><th>选中轮Top3/5同分天数</th><th>轨迹最大Top5同分天数</th><th>反序观察最佳轮</th><th>反序停止轮</th><th>峰值进程RSS</th></tr>']
        for r in summary['early_stopping']:
            page.append(f'<tr><td>{NAMES[r["variant"]]} / {r["treatment"]} / {r["seed"]}</td><td>{r["best_iteration"]}</td><td>{r["observed_rounds"]}{"（上限）" if r["hit_200_round_cap"] else ""}</td><td>{r["selected_boundary_ties"].get("3",0)} / {r["selected_boundary_ties"].get("5",0)}</td><td>{r["any_top5_boundary_tie_days"]}</td><td>{r["reverse_observed_best"]}</td><td>{r["reverse_stop_observed"] or "未观察到"}</td><td>{r["max_rss_GiB"]:.2f} GiB</td></tr>')
        page.append('</table></div>')
    page+=['<h2>来源、状态与解释边界</h2>','<p>直接对照为最近H20/patience50；该对照不替代正式v2。仅有四个候选，不能据单个n宣布全体分档方法有效或无效。收益、夏普、波动和RankIC分别解释；输入变化减少不等于模型稳健性得到证明。本轮不晋升、不修改策略或生产配置。</p>','<p><a href="../configs/frozen-study.json">冻结方案</a> · <a href="../configs/prepared-inputs.json">标签与输入证据</a> · <a href="../docs/study-summary.json">数值摘要</a> · <a href="../docs/study-progress.json">逐候选/作业账本</a> · <a href="../docs/harness-state.json">正式Harness账本</a></p>','</main></html>']
    (BASE/'reports/detail.html').write_text('\n'.join(page))
    return summary,docs,complete

def publish():
    save_source(__file__)
    from backtest.scripts.register.experiment_registry import append_registry
    from backtest.scripts.maintenance.experiment_archive import _validate_metadata
    summary,docs,complete=render();progress=read(PROGRESS);plan=read(BASE/'configs/frozen-study.json')
    if 'quantile5' not in docs:print('draft report refreshed; no evaluated candidate to register');return
    subprocess.run([sys.executable,str(TMP/'plot.py')],cwd=ROOT,check=True)
    sources=[];refs=[]
    for name in ['control_new',*VARIANTS]:
        if name not in docs:continue
        p=BASE/'metrics'/('control-new.json' if name=='control_new' else f'{name}-new.json')
        source={'exp_id':EID+'/arms/'+name,'archive_path':str(BASE.relative_to(ROOT)),'date':'2026-11-06','state':'completed','phase':'M','phase_m_protocol':'v1','direction':'training-target','experiment_type':'training_target','display_name':NAMES[name],'hypothesis':plan['hypothesis'],'baseline_ref':plan['formal_baseline'],'data_version':'2026-11-03','seeds':SEEDS,'evaluation_mode':'historical_selection_window','portable_eval_output':str(p.relative_to(ROOT)),'eval_output':str(p.relative_to(ROOT)),'detail_report':str((BASE/'reports/detail.html').relative_to(ROOT)),'metrics':{**cell(docs[name]),'rank_ic_mean':official(docs[name])['h5']['rank_ic_mean']},'parent_experiment':EID,'source_role':'paired_continuous_control' if name=='control_new' else 'internal_scientific_candidate','source_registration':'Covered by parent label-grading formal event','diagnostic_only':True,'cleanup_retention_eligible':False,'configs':[str((BASE/'configs/frozen-study.json').relative_to(ROOT))],'result_dirs':[str(Path('backtest/result')/s['session']) for s in docs[name]['sessions']]}
        out=BASE/'source-records'/f'{name}.json';write(out,source);refs.append(source['exp_id']);sources.append({'path':str(out.relative_to(BASE)),'sha256':fingerprint(out)['sha256']})
    metadata=read(BASE/'metadata.json')
    # Existing platform grouping validates distinct horizons, so it cannot represent
    # four different encodings of H20. Use the normal study entry and its detail HTML.
    metadata.pop('training_target_comparison',None)
    metadata['change_summary']='H20/patience50四种分档；平台代表指标为预先指定的等样本5档，全部方案及同源连续对照见详细报告。'
    metadata['analysis']={'conclusion':f'{summary["completed_candidates"]}/4个方案已评估；平台摘要为等样本5档代表行，非综合分数或事后优胜者。','evidence':['reports/detail.html','docs/study-summary.json'],'limitations':'原生平台分组只支持不同训练期限；本轮H20标签编码比较在详细报告逐项展示。历史选型窗口，未晋升。','review_status':'draft','updated_at':'2026-11-06'}
    write(BASE/'metadata.json',metadata)
    write(BASE/'docs/internal-source-index.json',{'candidate_refs':refs,'source_records':sources,'platform_scope':'Normal parent experiment entry; generic same-H recipe groups unsupported by current platform. Detail HTML contains all candidates and the true paired control.'})
    _validate_metadata(ROOT,BASE/'metadata.json',metadata,'model')
    native=read(STATE);attempt=native['variants'][EID]['attempts'][-1]['attempt_id']
    sessions=[str(Path('backtest/result')/j['session']) for j in progress['jobs'] if j['status']=='succeeded']
    row={'exp_id':EID,'archive_path':str(BASE.relative_to(ROOT)),'date':'2026-11-06','state':'completed' if complete else 'running','phase':'M','phase_m_protocol':'v1','direction':'training-target','experiment_type':'training_target','hypothesis':plan['hypothesis'],'baseline_ref':plan['formal_baseline'],'data_version':'2026-11-03','seeds':SEEDS,'train_pool':'all','test_pools':['all'],'evaluation_mode':'historical_selection_window','portable_eval_output':str((BASE/'metrics/quantile5-new.json').relative_to(ROOT)),'detail_report':str((BASE/'reports/detail.html').relative_to(ROOT)),'metrics':{**cell(docs['quantile5']),'rank_ic_mean':official(docs['quantile5'])['h5']['rank_ic_mean']},'representative_candidate':'quantile5 chosen before returns; not an aggregate or selected winner','paired_control_ref':plan['paired_control'],'internal_candidates':copy.deepcopy(progress['scientific_candidates']),'execution_audit':{'scientific_candidates':4,'actual_new_fits':len(progress['jobs']),'successful_fits':summary['model_fits_succeeded'],'prior_fits':111,'cumulative_fits':111+len(progress['jobs']),'native_lifecycle_scope':'one study attempt plus exact per-fit ledger; internal science tracked in supplemental ledger'},'configs':[str((BASE/'configs'/f).relative_to(ROOT)) for f in ['frozen-study.json','prepared-inputs.json','harness-plan.json','evaluation.yaml']],'result_dirs':sessions+['backtest/result/20261106_label_grading'],'harness':{'campaign_id':'label-grading-p50-20261106-v1','attempt_id':attempt},'conclusion':f'{summary["completed_candidates"]}/4个候选已完成官方评估；所有候选、旧标签配对和局限见详细报告。尚未晋升。','study_summary':str((BASE/'docs/study-summary.json').relative_to(ROOT)),'diagnostic_only':True,'cleanup_retention_eligible':False}
    append_registry(ROOT/'backtest/experiments/registry.jsonl',row)
    subprocess.run([sys.executable,str(ROOT/'backtest/scripts/report/build_phase_m_v1_report.py')],cwd=ROOT,check=True)
    for name in VARIANTS:
        if name in docs:progress['scientific_candidates'][name]['status']='completed'
    progress['status']='evaluated' if complete else 'running';progress.setdefault('registration_receipts',[]).append({'completed_candidates':summary['completed_candidates'],'registry':fingerprint(ROOT/'backtest/experiments/registry.jsonl'),'detail':fingerprint(BASE/'reports/detail.html'),'summary':fingerprint(BASE/'docs/study-summary.json')});write(PROGRESS,progress)
    print('registered/reported candidates',summary['completed_candidates'],flush=True)

if __name__=='__main__':
    if len(sys.argv)>1 and sys.argv[1]=='draft':render()
    else:publish()
